const req = $input.first().json;
const SUPPORTED = ["upsert_contact", "create_deal", "create_task"];
const rawOp = String(req.op == null ? "" : req.op).trim().toLowerCase();

let payload = {};
let payloadError = "";
const rawPayload = req.payload;
if (rawPayload && typeof rawPayload === "object") {
  payload = rawPayload;
} else if (typeof rawPayload === "string" && rawPayload.trim()) {
  try { payload = JSON.parse(rawPayload); }
  catch (e) { payloadError = "payload is not valid JSON: " + e.message; }
}
if (!payload || typeof payload !== "object") { payload = {}; }

function fnv(s) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
  return (h >>> 0).toString(16).padStart(8, "0");
}
const canonical = JSON.stringify(payload);
const payloadDigest = fnv(rawOp + "|" + canonical) + fnv(canonical + "|" + rawOp);

// Tenant is part of every key in this service. A tenant id that could smuggle a
// separator into a composite key would let one tenant address another's rows,
// so the character set is restricted rather than escaped.
const rawTenant = String(req.tenant_id || "default").trim().toLowerCase();
const tenantId = /^[a-z0-9][a-z0-9_-]{0,62}$/.test(rawTenant) ? rawTenant : "";
const traceId = String(req.trace_id || "").trim().slice(0, 64);

const rawDry = req.dry_run;
const dryRun = String(rawDry === undefined || rawDry === null || rawDry === "" ? "true" : rawDry).toLowerCase() !== "false";
const leadKey = String(req.lead_key || payload.lead_key || "").trim().toLowerCase();

// Tenant-scoped. Without the prefix, two tenants sending the same lead collide
// in the write ledger and the second one silently receives the first one's id.
const suppliedKey = String(req.idempotency_key || "").trim();
const idem = tenantId + ":" + (suppliedKey || (rawOp + "-" + (leadKey || "anon") + "-" + payloadDigest));

const errors = [];
if (!tenantId) { errors.push("tenant_id must match ^[a-z0-9][a-z0-9_-]{0,62}$; got " + JSON.stringify(rawTenant)); }
if (payloadError) { errors.push(payloadError); }
if (SUPPORTED.indexOf(rawOp) === -1) { errors.push("op must be one of " + SUPPORTED.join(", ")); }
if (rawOp === "upsert_contact" && !payload.email) { errors.push("payload.email is required for upsert_contact"); }
if (rawOp === "create_deal" && !payload.deal_name) { errors.push("payload.deal_name is required for create_deal"); }
if (rawOp === "create_deal" && !payload.stage) { errors.push("payload.stage is required for create_deal"); }
if (rawOp === "create_task" && !payload.body) { errors.push("payload.body is required for create_task"); }

const contactIds = Array.isArray(payload.associated_contact_ids)
  ? payload.associated_contact_ids.map(function (v) { return String(v); })
  : (payload.contact_id ? [String(payload.contact_id)] : []);

// ---------------------------------------------------------------------------
// HubSpot request construction
//
// Built here, in ordinary JavaScript, rather than inside an HTTP node
// expression. Two reasons: the field mapping is the part most likely to need
// changing and it is far easier to read here; and the dry-run branch can report
// the exact request that would have been sent, which is auditable evidence that
// does not require a credential to produce.
//
// Date-based API version. HubSpot's own guidance is that the version should be
// configuration rather than hard-coded, so the caller may override it.
// ---------------------------------------------------------------------------
// Operations this deployment is configured to issue. create_task is off because
// POST /crm/objects/{version}/tasks additionally requires crm.objects.contacts.read,
// which would grant read access to every contact in the portal. Declared here so
// there is one source of truth, rather than inferred downstream from the shape of
// whatever a disabled node happened to pass through.
const ENABLED_OPS = { upsert_contact: true, create_deal: true, create_task: false };
const operationDisabled = SUPPORTED.indexOf(rawOp) !== -1 && ENABLED_OPS[rawOp] === false;

const apiVersion = String(payload.api_version || "2026-09");
if (!/^[0-9]{4}-[0-9]{2}$/.test(apiVersion)) {
  errors.push("payload.api_version must look like 2026-09; got " + JSON.stringify(apiVersion));
}
const hsBase = "https://api.hubapi.com/crm/objects/" + apiVersion;

function put(target, key, value) {
  if (value !== undefined && value !== null && String(value) !== "") {
    target[key] = String(value);
  }
}

const contactProps = {};
put(contactProps, "email", payload.email);
put(contactProps, "firstname", payload.first_name);
put(contactProps, "lastname", payload.last_name);
put(contactProps, "company", payload.company_name);
put(contactProps, "jobtitle", payload.job_title);
put(contactProps, "phone", payload.phone);
put(contactProps, "website", payload.website);
put(contactProps, "swarm_lead_score", payload.lead_score);
put(contactProps, "swarm_lead_tier", payload.lead_tier);

const dealProps = {};
put(dealProps, "dealname", payload.deal_name);
put(dealProps, "dealstage", payload.stage);
put(dealProps, "amount", payload.amount);
put(dealProps, "description", payload.description);
// HubSpot requires `pipeline` alongside `dealstage` on the 2026-09 deals
// endpoint and does not infer it from the stage: a create without it fails
// 400 VALIDATION_ERROR naming [pipeline]. "default" is the id of the default
// deal pipeline present in every portal; a caller may still override it.
put(dealProps, "pipeline", payload.pipeline || "default");

const taskProps = {};
put(taskProps, "hs_timestamp", payload.due_date || new Date(Date.now() + 86400000).toISOString());
put(taskProps, "hs_task_subject", payload.subject || "Revenue Swarm follow-up");
put(taskProps, "hs_task_body", payload.body);
taskProps.hs_task_status = "NOT_STARTED";
taskProps.hs_task_priority = String(payload.priority || "MEDIUM");

// HUBSPOT_DEFINED association type ids: deal -> contact is 3, task -> contact
// is 204. Both travel inside the create call, so there is no separate
// associations request and no associations scope to grant.
function contactAssociations(typeId) {
  const out = [];
  for (let i = 0; i < contactIds.length; i++) {
    out.push({
      to: { id: contactIds[i] },
      types: [{ associationCategory: "HUBSPOT_DEFINED", associationTypeId: typeId }]
    });
  }
  return out;
}

const hubspot = {
  api_version: apiVersion,
  upsert_contact: {
    method: "POST",
    url: hsBase + "/contacts/batch/upsert",
    // Upsert by email in one call. There is no single-object upsert, and a
    // create-then-patch-on-conflict pair would need a read to learn the id.
    body: { inputs: [{ idProperty: "email", id: String(payload.email || ""), properties: contactProps }] }
  },
  create_deal: {
    method: "POST",
    url: hsBase + "/deals",
    body: { properties: dealProps, associations: contactAssociations(3) }
  },
  create_task: {
    method: "POST",
    url: hsBase + "/tasks",
    body: { properties: taskProps, associations: contactAssociations(204) }
  }
};

return [{ json: {
  op: rawOp,
  payload: payload,
  payload_digest: payloadDigest,
  dry_run: dryRun,
  lead_key: leadKey,
  tenant_id: tenantId,
  trace_id: traceId,
  idempotency_key: idem,
  source_workflow: String(req.source_workflow || "unknown"),
  associated_contact_ids: contactIds,
  associated_contact_csv: contactIds.join(","),
  hubspot: hubspot,
  operation_disabled: operationDisabled,
  valid: errors.length === 0,
  validation_errors: errors,
  started_at_ms: Date.now()
} }];

const CAPTURES = ["Capture Contact Write", "Capture Deal Write", "Capture Task Write", "Simulate CRM Write", "Capture Replay", "Capture Rejected Write"];
let verdict = null;
for (const name of CAPTURES) {
  try {
    const items = $(name).all();
    if (items && items.length) { verdict = items[0].json; break; }
  } catch (e) { }
}
if (!verdict) {
  verdict = { ok: false, status: "no_branch_ran", object_type: "none", object_id: "", errors: ["No capture node produced a verdict. This is a wiring bug, not a CRM failure."] };
}

// Tenant and trace come from the request, never from the branch that ran, so a
// caller can always correlate the answer it gets back.
const req = $("Normalise CRM Request").first().json;
verdict.tenant_id = req.tenant_id;
verdict.trace_id = req.trace_id;
return [{ json: verdict }];

const req = $("Normalise CRM Request").first().json;
const TYPES = { upsert_contact: "contact", create_deal: "deal", create_task: "task" };
const objectType = TYPES[req.op] || "unknown";

const simulatedId = "sim-" + objectType + "-" + req.payload_digest.slice(0, 12);
const planned = (req.hubspot && req.hubspot[req.op]) ? req.hubspot[req.op] : null;

return [{ json: {
  ok: true,
  op: req.op,
  object_type: objectType,
  object_id: simulatedId,
  is_new: true,
  status: "simulated",
  replayed: false,
  simulated: true,
  crm: "none",
  idempotency_key: req.idempotency_key,
  lead_key: req.lead_key,
  payload_digest: req.payload_digest,
  dry_run: true,
  errors: [],
  // The exact request the live branch would have issued. Auditable without a
  // credential, and the thing to diff when a mapping changes.
  planned_request: planned,
  api_version: req.hubspot ? req.hubspot.api_version : null,
  note: "dry_run=true: no HubSpot call was made. The id is derived from the payload digest, so the same payload always simulates to the same id.",
  latency_ms: Date.now() - Number(req.started_at_ms)
} }];

const req = $("Normalise CRM Request").first().json;
const res = $input.first().json || {};

// The 2026-09 batch upsert answers {status, results:[{id, properties, ...}]}.
// The other shapes are the legacy v1 responses, kept so a rolled-back workflow
// version still reads its own output correctly.
const batch = (res.results && res.results.length) ? res.results[0] : null;
const id = (batch && batch.id)
  || res.id
  || res.vid
  || (res.properties && res.properties.hs_object_id)
  || "";

// Whether the contact was newly created is only reported when the response
// actually says so. A guess derived from createdAt === updatedAt would be wrong
// for any contact updated within the same millisecond it was created, and a
// wrong boolean in an audit record is worse than an absent one.
let isNew = null;
if (batch && typeof batch.new === "boolean") { isNew = batch.new; }
else if (res.isNew !== undefined) { isNew = !!res.isNew; }

return [{ json: {
  ok: !!id,
  op: req.op,
  object_type: "contact",
  object_id: String(id),
  is_new: isNew,
  status: id ? "written" : "write_returned_no_id",
  replayed: false,
  simulated: false,
  crm: "hubspot",
  api_version: req.hubspot ? req.hubspot.api_version : null,
  idempotency_key: req.idempotency_key,
  lead_key: req.lead_key,
  payload_digest: req.payload_digest,
  dry_run: false,
  errors: [],
  latency_ms: Date.now() - Number(req.started_at_ms)
} }];

const req = $("Normalise CRM Request").first().json;
const res = $input.first().json || {};

// 2026-09 object create answers {id, properties, createdAt, ...}. res.dealId is
// the legacy v1 shape.
const id = res.id || res.dealId || (res.properties && res.properties.hs_object_id) || "";

return [{ json: {
  ok: !!id,
  op: req.op,
  object_type: "deal",
  object_id: String(id),
  is_new: true,
  status: id ? "written" : "write_returned_no_id",
  replayed: false,
  simulated: false,
  crm: "hubspot",
  api_version: req.hubspot ? req.hubspot.api_version : null,
  associated_contact_ids: req.associated_contact_ids,
  idempotency_key: req.idempotency_key,
  lead_key: req.lead_key,
  payload_digest: req.payload_digest,
  dry_run: false,
  errors: [],
  latency_ms: Date.now() - Number(req.started_at_ms)
} }];

const req = $("Normalise CRM Request").first().json;
const res = $input.first().json || {};

// A disabled n8n node passes its input straight through to the next node. So
// when HubSpot Create Task is disabled, what arrives here is the request this
// service built, not a HubSpot response. Detect that specifically rather than
// reporting "no id", which is true but blames the wrong thing.
// Set by Normalise CRM Request from ENABLED_OPS. Deterministic: it does not
// depend on what a disabled n8n node passes through, which is the item as it
// left the write-ledger lookup rather than the original request.
const isPassthrough = req.operation_disabled === true;

if (isPassthrough) {
  return [{ json: {
    ok: false,
    op: req.op,
    object_type: "task",
    object_id: "",
    is_new: null,
    status: "skipped_operation_disabled",
    replayed: false,
    simulated: false,
    crm: "hubspot",
    api_version: req.hubspot ? req.hubspot.api_version : null,
    idempotency_key: req.idempotency_key,
    lead_key: req.lead_key,
    payload_digest: req.payload_digest,
    dry_run: false,
    errors: [
      "create_task is disabled in this deployment: POST /crm/objects/{version}/tasks additionally requires crm.objects.contacts.read, which would grant read access to every contact in the portal"
    ],
    latency_ms: Date.now() - Number(req.started_at_ms)
  } }];
}

// 2026-09 answers {id, properties, ...}. res.engagement.id is the legacy
// engagements v1 shape.
const id = res.id || (res.engagement && res.engagement.id) || (res.properties && res.properties.hs_object_id) || "";

return [{ json: {
  ok: !!id,
  op: req.op,
  object_type: "task",
  object_id: String(id),
  is_new: true,
  status: id ? "written" : "write_returned_no_id",
  replayed: false,
  simulated: false,
  crm: "hubspot",
  api_version: req.hubspot ? req.hubspot.api_version : null,
  associated_contact_ids: req.associated_contact_ids,
  idempotency_key: req.idempotency_key,
  lead_key: req.lead_key,
  payload_digest: req.payload_digest,
  dry_run: false,
  errors: [],
  latency_ms: Date.now() - Number(req.started_at_ms)
} }];

// A run nonce keeps the suite deterministic across repeat runs: C01 is always a
// fresh key so it simulates, and C02 reuses that same key so it must replay.
const nonce = String($execution.id) + "-" + Date.now().toString(36);
const leadKey = "suite-" + nonce + "@example.com";

const contactPayload = JSON.stringify({
  email: leadKey,
  first_name: "Ada",
  last_name: "Lovelace",
  company_name: "Analytical Engines",
  job_title: "VP Engineering",
  lead_score: 87,
  lead_tier: "HOT"
});

const fixtures = [
  { case_id: "C01", note: "valid contact upsert, dry run", op: "upsert_contact", payload: contactPayload, lead_key: leadKey, tenant_id: "acme", dry_run: "true", idempotency_key: "", expect_status: "simulated", expect_type: "contact", expect_ok: true },
  { case_id: "C02", note: "same payload again must replay, not write twice", op: "upsert_contact", payload: contactPayload, lead_key: leadKey, tenant_id: "acme", dry_run: "true", idempotency_key: "", expect_status: "replayed", expect_type: "contact", expect_ok: true },
  { case_id: "C03", note: "contact without email is rejected before any CRM call", op: "upsert_contact", payload: JSON.stringify({ first_name: "NoEmail" }), lead_key: "c03-" + nonce, tenant_id: "acme", dry_run: "true", idempotency_key: "", expect_status: "rejected", expect_type: "none", expect_ok: false },
  { case_id: "C04", note: "valid deal, dry run", op: "create_deal", payload: JSON.stringify({ deal_name: "Analytical Engines - pilot", stage: "qualifiedtobuy", amount: "24000", contact_id: "1201" }), lead_key: "c04-" + nonce, tenant_id: "acme", dry_run: "true", idempotency_key: "", expect_status: "simulated", expect_type: "deal", expect_ok: true },
  { case_id: "C05", note: "deal without stage is rejected", op: "create_deal", payload: JSON.stringify({ deal_name: "No stage" }), lead_key: "c05-" + nonce, tenant_id: "acme", dry_run: "true", idempotency_key: "", expect_status: "rejected", expect_type: "none", expect_ok: false },
  { case_id: "C06", note: "valid follow-up task, dry run", op: "create_task", payload: JSON.stringify({ subject: "Call Ada", body: "Score 87 (HOT). Budget signal explicit.", contact_id: "1201" }), lead_key: "c06-" + nonce, tenant_id: "acme", dry_run: "true", idempotency_key: "", expect_status: "simulated", expect_type: "task", expect_ok: true },
  { case_id: "C07", note: "unknown op never reaches HubSpot", op: "delete_everything", payload: JSON.stringify({ email: "x@example.com" }), lead_key: "c07-" + nonce, tenant_id: "acme", dry_run: "false", idempotency_key: "", expect_status: "rejected", expect_type: "none", expect_ok: false },
  { case_id: "C08", note: "a second tenant sending the identical lead must not be suppressed by the first", op: "upsert_contact", payload: contactPayload, lead_key: leadKey, tenant_id: "globex", dry_run: "true", idempotency_key: "", expect_status: "simulated", expect_type: "contact", expect_ok: true },
  { case_id: "C09", note: "a malformed tenant id is refused rather than escaped into a key", op: "upsert_contact", payload: contactPayload, lead_key: leadKey, tenant_id: "acme:globex", dry_run: "true", idempotency_key: "", expect_status: "rejected", expect_type: "none", expect_ok: false }
];

return fixtures.map(function (f) {
  f.source_workflow = "11-test-suite";
  f.trace_id = "trace-" + nonce + "-" + f.case_id;
  return { json: f };
});

// Execute Sub-workflow double-wraps its output. Slimming here also keeps the
// loop's contextData small enough to read back from the execution log.
const raw = $input.first().json;
const res = (raw && raw.json) ? raw.json : raw;
const fixture = $("CRM Fixture Loop").first().json;
return [{ json: {
  case_id: fixture.case_id,
  note: fixture.note,
  op: fixture.op,
  tenant_id: fixture.tenant_id,
  expect_status: fixture.expect_status,
  expect_type: fixture.expect_type,
  expect_ok: fixture.expect_ok,
  actual_status: res.status,
  actual_type: res.object_type,
  actual_ok: res.ok === true,
  actual_tenant: res.tenant_id,
  actual_trace: res.trace_id,
  object_id: res.object_id,
  errors: res.errors || [],
  latency_ms: res.latency_ms
} }];

// The done branch of splitInBatches carries every processed item.
// $('Slim CRM Result').all() would only return the final loop run.
const rows = $input.all().map(function (i) { return i.json; });
const byCase = {};
rows.forEach(function (r) { byCase[r.case_id] = r; });

const cases = rows.map(function (r) {
  const checks = [];
  checks.push({ name: "status", pass: r.actual_status === r.expect_status, expected: r.expect_status, actual: r.actual_status });
  checks.push({ name: "object_type", pass: r.actual_type === r.expect_type, expected: r.expect_type, actual: r.actual_type });
  checks.push({ name: "ok", pass: r.actual_ok === r.expect_ok, expected: r.expect_ok, actual: r.actual_ok });
  if (r.expect_status === "simulated") {
    checks.push({ name: "simulated_id_prefix", pass: String(r.object_id || "").indexOf("sim-") === 0, expected: "sim-*", actual: r.object_id });
  }
  if (r.expect_status === "rejected") {
    checks.push({ name: "rejection_explained", pass: (r.errors || []).length > 0, expected: ">0 errors", actual: (r.errors || []).length });
  }
  // Trace id must survive every path, including the rejected ones.
  checks.push({ name: "trace_echoed", pass: String(r.actual_trace || "").indexOf("trace-") === 0, expected: "trace-*", actual: r.actual_trace });
  const failed = checks.filter(function (c) { return !c.pass; });
  return { case_id: r.case_id, note: r.note, passed: failed.length === 0, checks: checks, latency_ms: r.latency_ms };
});

// Cross-tenant isolation is a property of the pair, not of either case alone.
const c01 = byCase["C01"];
const c08 = byCase["C08"];
if (c01 && c08) {
  const distinct = c01.object_id !== c08.object_id || c01.actual_tenant !== c08.actual_tenant;
  cases.push({
    case_id: "C08x",
    note: "cross-tenant isolation: identical leads in two tenants must not share a write",
    passed: c08.actual_status === "simulated" && distinct,
    checks: [
      { name: "second_tenant_not_replayed", pass: c08.actual_status === "simulated", expected: "simulated", actual: c08.actual_status },
      { name: "tenants_distinct", pass: c01.actual_tenant !== c08.actual_tenant, expected: "acme != globex", actual: c01.actual_tenant + " vs " + c08.actual_tenant }
    ],
    latency_ms: c08.latency_ms
  });
}

const passed = cases.filter(function (c) { return c.passed; }).length;
return [{ json: {
  suite: "11-crm-sync-service",
  run_at: new Date().toISOString(),
  execution_id: $execution.id,
  total: cases.length,
  passed: passed,
  failed: cases.length - passed,
  all_passed: passed === cases.length && cases.length === 10,
  cases: cases
} }];
